// === LWB Gemini Enum Patch v3 ===
//
// DEBUG:浏览器控制台过滤 'LWB-Gemini-Enum-Patch' 即可看 log
//
// 背景:LWB Scene Planner 用 Gemini(直连/中转)走 @google/genai SDK。
//      SDK 内部用裸 `fetch(e, t)` 标识符(line 9468),每次调用查 globalThis.fetch。
//      SDK 在 client 初始化时 bE() 返回的 fetch 被缓存到 this.fetch,
//      但 apiCall() 仍用裸 fetch 查全局 —— 只要劫持 globalThis.fetch,即可拦截。
//
// 关键陷阱:
//  1. 酒馆助手脚本默认跑在 iframe 里,iframe 的 window.fetch 不影响主窗口
//     → 必须劫持 window.parent.fetch(主窗口)
//  2. 简单赋值 `window.parent.fetch = patched` 之后,LWB 模块再读 fetch
//     仍然读到劫持函数 —— 但需确认 SDK 不会缓存到 this.fetch 后只走缓存路径
//
// 解决:用 Object.defineProperty 把主窗口的 fetch 改成动态 getter,
//      任何代码(包括 SDK)访问主窗口的 fetch 都拿到我们的劫持函数。
//      原始 fetch 通过闭包保存。
//
// 回滚:酒馆助手禁用此脚本 + 刷新页面。

$(errorCatched(() => {
  const TAG = 'LWB-Gemini-Enum-Patch';
  const LOG = `[${TAG}]`;
  const log = (...a) => console.log(LOG, ...a);
  const warn = (...a) => console.warn(LOG, ...a);

  // 拿主窗口(top-most)
  const topWin = window.top === window ? window : window.top;

  // 标记:避免重入
  if (topWin.__lwbGeminiPatchInstalled) {
    log('already patched, skip');
    return;
  }
  topWin.__lwbGeminiPatchInstalled = true;

  // 递归清洗 schema:把 enum 数组里的空字符串删掉,enum 空了就删字段
  const cleanEmptyEnums = (node) => {
    if (!node || typeof node !== 'object') return 0;
    let touched = 0;
    if (Array.isArray(node)) {
      for (const item of node) touched += cleanEmptyEnums(item);
      return touched;
    }
    for (const key of Object.keys(node)) {
      const value = node[key];
      if (key === 'enum' && Array.isArray(value)) {
        const filtered = value.filter((v) => v !== '' && v !== null && v !== undefined);
        if (filtered.length !== value.length) {
          touched += value.length - filtered.length;
          if (filtered.length === 0) {
            delete node[key];
          } else {
            node[key] = filtered;
          }
        }
        continue;
      }
      touched += cleanEmptyEnums(value);
    }
    return touched;
  };

  // body 解析:字符串/对象都接,form/二进制/无 body 都原样 pass
  // 跨 realm:不用 instanceof,用 duck typing
  const isURLSearchParams = (v) =>
    v != null && typeof v === 'object' && typeof v.append === 'function'
      && typeof v.toString === 'function' && v[Symbol.toStringTag] === 'URLSearchParams';

  const readBody = (body) => {
    if (body == null) return null;
    if (typeof body === 'string') {
      try { return { parsed: JSON.parse(body), stringify: true }; }
      catch { return null; }
    }
    if (isURLSearchParams(body)) return null;
    if (body instanceof ArrayBuffer || ArrayBuffer.isView(body)) return null;
    if (body instanceof Blob) return null;
    if (body instanceof FormData) return null;
    if (body instanceof ReadableStream) return null;
    if (typeof body === 'object') return { parsed: body, stringify: true };
    return null;
  };

  // 我们的劫持 fetch
  const patchedFetch = async function patchedFetch(input, init) {
    const url = typeof input === 'string' ? input : input instanceof Request ? input.url : '';
    const nextInit = init ? { ...init } : {};
    const result = readBody(nextInit.body);
    if (result && Array.isArray(result.parsed.tools) && result.parsed.tools.length > 0) {
      let touched = 0;
      for (const tool of result.parsed.tools) touched += cleanEmptyEnums(tool);
      if (touched > 0) {
        log(`cleaned ${touched} empty enum entries in tools schema → ${url}`);
        nextInit.body = result.stringify ? JSON.stringify(result.parsed) : result.parsed;
      }
    }
    return topWin.__lwbGeminiOriginalFetch.call(topWin, input, nextInit);
  };

  // 用 defineProperty 把主窗口 fetch 改成 getter,
  // 保证任何代码(包括 SDK 内部裸 fetch 标识符)读到的都是劫持函数
  let realFetch;
  try {
    realFetch = Object.getOwnPropertyDescriptor(topWin, 'fetch');
    // 拿到原 fetch 引用
    const originalFetch = realFetch?.value || topWin.fetch;

    topWin.__lwbGeminiOriginalFetch = originalFetch.bind(topWin);

    Object.defineProperty(topWin, 'fetch', {
      configurable: true,
      enumerable: true,
      get() { return patchedFetch; },
      set(v) { topWin.__lwbGeminiOriginalFetch = v.bind ? v.bind(topWin) : v; },
    });

    log('installed on top window via defineProperty');
  } catch (e) {
    warn('defineProperty failed, falling back to simple assignment:', e.message);
    topWin.__lwbGeminiOriginalFetch = topWin.fetch.bind(topWin);
    topWin.fetch = patchedFetch;
    log('installed on top window via simple assignment (fallback)');
  }
}));
